            j += 1
        elif arr1[i] < arr2[j]:
            last_1 = arr1[i]
            i += 1
        else:
            last_1 = arr2[j]
            j += 1

    if (n1 + n2) % 2 == 1:
        return last_1
    else:
        return (last_1 + last_2) / 2
